420	// CreateHandover 由交班班次向同岗位接班班次发起交接。
421	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
422	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
423	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
424	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
425	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
426	// 要求仅对首次发起生效。
427	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
428		fromShiftID = clean(fromShiftID)
429		toShiftID = clean(toShiftID)
430	
431		var result Handover
432		err := svc.store.mutate(func(d *Data) error {
433			from, _ := findShift(d, fromShiftID)
434			to, _ := findShift(d, toShiftID)
435			if from == nil {
436				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
437			}
438			if to == nil {
439				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
440			}
441			if from.ID == to.ID {
442				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
443			}
444			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
445			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
446			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
447			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
448			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
449			// 存在与交给自身的校验仍在其前。
450			for i := range d.Handovers {
451				if d.Handovers[i].FromShiftID == from.ID {
452					existing := &d.Handovers[i]
453					result = *existing
454					if existing.ToShiftID != to.ID {
455						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
456							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
457					}
458					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
459				}
460			}
461	
462			if from.Position != to.Position {
463				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
464					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
465			}
466	
467			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
468			// 交班班次已经结束，重叠区间须有说明。
469			if to.Closed {
470				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
471			}
472			if to.Start.Before(from.Start) {
473				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
474					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
475					from.ID, from.Start.Format(time.RFC3339))
476			}
477			if !from.Closed {
478				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
479					ErrShiftNotClosed, from.ID)
480			}
481			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
482				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
483					ErrOverlap, from.ID, to.ID)
484			}
485	
486			entries := []HandoverEntry{}
487			for i := range d.Items {
488				it := &d.Items[i]
489				if it.CurrentShiftID == from.ID && !it.Closed {
490					entries = append(entries, HandoverEntry{
491						ItemID:      it.ID,
492						Content:     it.Content,
493						Severity:    it.Severity,
494						Constraints: it.Constraints,
495						FollowOwner: it.FollowOwner,
496						Status:      EntryPending,
497					})
498				}
499			}
500			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
501	
502			d.HandoverSeq++
503			now := svc.now()
504			h := Handover{
505				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
506				Position:    from.Position,
507				FromShiftID: from.ID,
508				ToShiftID:   to.ID,
509				CreatedAt:   now,
510				Entries:     entries,
511			}
512			if len(entries) == 0 {
513				// 空清单直接完成。
514				h.CompletedAt = &now
515			}
516			d.Handovers = append(d.Handovers, h)
517			result = h
518			return nil
519		})
520		return result, err
521	}
