726	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
727	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
728	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
729	// 当前保存的处理结果是退回、却没有任何退回轮次记录时（旧数据缺失），仍在时间线
730	// 中呈现这次已发生的退回，处理人与处理时间各自使用该项当前保存的信息（缺失分别
731	// 标为未记录），并标明退回历史不完整、原因未记录；不编造轮次序号、原因、补充或
732	// 重新提交经过，也不拿交接发起时间补齐处理时间。待处理、确认接收、继续跟踪、
733	// 结果缺失或无法识别的记录不据残留的处理人与时间认定发生退回。
734	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
735	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
736	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
737	// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
738	// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
739	// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
740	// 不改变事项、交接进度或班次结束时记录。
741	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
742		itemID = clean(itemID)
743		d := &svc.store.data
744		it, _ := findItem(d, itemID)
745		if it == nil {
746			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
747		}
748		j := ItemJourney{Item: *it}
749	
750		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
751		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
752		// 该轮重新提交、后续处理）。
753		type keyedEvent struct {
754			ev    JourneyEvent
755			group string // "" 表示事项自身事件，否则为交接编号
756			ord   int    // 同一（时刻、分组）内的先后
757		}
758		var events []keyedEvent
759		seq := 0
760		add := func(ev JourneyEvent, group string) {
761			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
762			seq++
763		}
764	
765		// 接收记录的合并判定集中在 receivedMerge（见 received_merge.go）：遍历各次
766		// 交接清单时标记与某次接收同属一次的事项 received 事件，该事件随后只以信息
767		// 更全的交接事件展示。未标记的 received 事件（缺交接编号或交班班次的旧
768		// 说明、指向其他交接/班次/方式的说明、自由文字或残缺说明等）在下面原样保留。
769		merge := newReceivedMerge(it.Events)
770	
771		hs := append([]Handover(nil), d.Handovers...)
772		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
773		for k := range hs {
774			h := &hs[k]
775			e, _ := findEntry(h, itemID)
776			if e == nil {
777				continue
778			}
779			j.HasHandovers = true
780			j.Results = append(j.Results, EntryView{
781				HandoverID: h.ID,
782				FromShift:  h.FromShiftID,
783				ToShift:    h.ToShiftID,
784				Entry:      *e,
785			})
786	
787			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
788			add(JourneyEvent{
789				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
790				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
791			}, h.ID)
792			for _, r := range e.Rounds {
793				add(JourneyEvent{
794					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
795					Kind: "return", Operator: r.ReturnOperator,
796					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
797					RoundSeq: r.Seq, Reason: r.Reason,
798				}, h.ID)
799				if r.ResubmittedAt != nil {
800					add(JourneyEvent{
801						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
802						Kind: "resubmit", Operator: r.SupplementOperator,
803						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
804						RoundSeq: r.Seq, Supplement: r.Supplement,
805						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
806					}, h.ID)
807				}
808			}
809			if e.Status == EntryReturned && len(e.Rounds) == 0 {
810				// 当前保存的结果是退回，却没有任何退回轮次记录（旧数据缺失）：
811				// 退回确实发生过，处理经过必须呈现这一事实，不能像没发生过退回一样
812				// 只列发起交接；但原因、轮次序号、补充与重新提交经过都没有可靠记录，
813				// 只能使用该项当前保存的处理人与处理时间，并标明退回历史不完整。
814				// 不编造第几次退回或退回原因，也不拿交接发起时间补齐处理时间。
815				ev := JourneyEvent{
816					Kind: "return-incomplete", Operator: e.Operator,
817					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
818					HistoryIncomplete: true,
819				}
820				if validProcessedAt(e.ProcessedAt) {
821					ev.At, ev.TimeKnown = *e.ProcessedAt, true
822				}
823				add(ev, h.ID)
824			}
825			if e.Status.Received() {
826				rcpt := receiptFromEntry(h, e)
827				ev := JourneyEvent{
828					Kind: rcpt.kind, Operator: e.Operator,
829					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
830					TrackingNote: e.TrackingNote,
831					// 继续跟踪当时指定的后续负责人取自交接记录快照，
832					// 之后修改事项负责人不改变这里的历史值。
833					FollowOwner: e.FollowOwner,
834				}
835				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
836				// 时间标为未记录，排在有真实时间的事件之后；这种凭据 timeKnown
837				// 为 false，consider 不会合并任何事项事件（也不拿发起时间代替）。
838				if rcpt.timeKnown {
839					ev.At, ev.TimeKnown = rcpt.at, true
840				}
841				add(ev, h.ID)
842				// 标记与本次接收同属一次的事项 received 事件；合并依据全部在
843				// sameReceivedEvent 中：操作人与实际时刻相同，且说明完整记载
844				// 交接编号、交班、接班班次与接收方式并逐项一致。缺归属信息的
845				// 旧说明、残缺或自由文字说明一律不合并，原样作为独立接收历史。
846				merge.consider(rcpt)
847			}
848		}
849	
850		// 事项自身历史：建立、修改、关闭原样保留；未被合并掉的 received 事件
851		// （旧数据、指向其他归属的说明、自由文字等）也原样保留。
852		for i, iev := range it.Events {
853			if iev.Kind == "received" && merge.isUsed(i) {
854				continue
855			}
856			add(JourneyEvent{
857				At: iev.At, TimeKnown: !iev.At.IsZero(),
858				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
859			}, "")
860		}
861	
862		sort.SliceStable(events, func(i, k int) bool {
863			a, b := events[i], events[k]
864			if a.ev.TimeKnown != b.ev.TimeKnown {
865				return a.ev.TimeKnown
866			}
867			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
868				return a.ev.At.Before(b.ev.At)
869			}
870			if a.group != b.group {
871				return a.group < b.group
872			}
873			return a.ord < b.ord
874		})
875		for _, ke := range events {
876			j.Events = append(j.Events, ke.ev)
877		}
878		return j, nil
879	}
880	
881	// GetHandover 按编号查询交接。
882	func (svc *Service) GetHandover(id string) (Handover, error) {
883		h, _ := findHandover(&svc.store.data, clean(id))
884		if h == nil {
885			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
886		}
887		return *h, nil
888	}
889	
890	// ListHandovers 返回全部交接记录，按编号排序。
891	func (svc *Service) ListHandovers() []Handover {
892		out := append([]Handover(nil), svc.store.data.Handovers...)
893		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
894		return out
895	}
896	
897	// OverlapNotes 返回涉及指定班次的全部重叠说明。
898	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
899		shiftID = clean(shiftID)
900		out := []OverlapNote{}
901		for _, n := range svc.store.data.Notes {
902			if n.ShiftA == shiftID || n.ShiftB == shiftID {
903				out = append(out, n)
904			}
905		}
906		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
907		return out
908	}
909	
910	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
911	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
912	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
913	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
914		shiftID = clean(shiftID)
915		d := &svc.store.data
916		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
917		sh, _ := findShift(d, shiftID)
918		if sh == nil {
919			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
920		}
921		rep.Shift = *sh
922	
923		for _, n := range d.Notes {
924			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
925				rep.OverlapNotes = append(rep.OverlapNotes, n)
926			}
927		}
928		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
929	
930		switch {
931		case !sh.Closed:
932			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
933			rep.Items = currentItemsOfShift(d, sh.ID)
934		case sh.CloseRecord != nil:
935			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
936			rep.ItemsAtClose = true
937			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
938			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
939			for _, s := range rep.CloseItems {
940				if it, _ := findItem(d, s.ItemID); it != nil {
941					rep.LatestItems[s.ItemID] = *it
942				}
943			}
944		default:
945			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
946			rep.HistoryIncomplete = true
947			rep.Items = currentItemsOfShift(d, sh.ID)
948		}
949		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
950	
951		for i := range d.Handovers {
952			h := &d.Handovers[i]
953			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
954			if !involved {
955				continue
956			}
957			if h.FromShiftID == sh.ID {
958				cp := *h
959				rep.Outgoing = &cp
960			}
961			if h.ToShiftID == sh.ID {
962				rep.Incoming = append(rep.Incoming, *h)
963			}
964			for j := range h.Entries {
965				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
966					HandoverID: h.ID,
967					FromShift:  h.FromShiftID,
968					ToShift:    h.ToShiftID,
969					Entry:      h.Entries[j],
970				})
971			}
972		}
973		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
974		for k := range rep.Results {
975			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
976		}
977		return rep, nil
978	}
979

